#!/usr/bin/env python3
"""FS3 v206 - the Lucifer's shield as in FreeSpace.

    Lucifer    Her shield is the shield mesh of The Scroll of Atankharzim's
               Lucifer (it lies over her hull); a hit lights up the piece
               round where it struck, like on every other Shivan. The
               glimmering bubble of v205 is gone.
    Shields    A hit lies where it is seen to strike, on the part of the
               mesh in front (long hulls: no longer near her middle), and
               stays a patch round that point. Hulls without a shield mesh
               show none, as in FreeSpace.

Needs v205. Edits src/40_world.js and 59_field3d.js. New model file:
models_v206.zip (models/shields.json.gz with the Lucifer's mesh).
Run assemble.py 206 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v205 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "f3dShieldHit" not in _f:
    sys.exit("Abbruch: erst v205 einspielen.")
if "f3dShRay" in _f:
    sys.exit("v206 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
